package com.example.mydailyroutine;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Build;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    final int GREEN=Color.rgb(38,91,68), DEEP=Color.rgb(25,59,46), MINT=Color.rgb(226,239,229), BG=Color.rgb(248,249,245), TEXT=Color.rgb(42,53,46), MUTED=Color.rgb(119,132,122);
    LinearLayout root, content;
    String current="Today";
    String[] defaultNames={"Wake up","Drink water","Exercise","Take tablet","Drink water","Drink water","Evening walk","Sleep"};
    String[] defaultTimes={"06:00","07:00","07:30","09:00","11:00","14:00","18:00","22:30"};
    String[] exercises={"Wall push-ups","Chair sit-to-stand","Seated knee extensions","Seated arm raises","Shoulder rolls","Side leg raises"};
    String[] details={"8–10 gentle repetitions","8–10 controlled repetitions","10 repetitions each leg","10 slow repetitions","10 circles each direction","8–10 repetitions each side"};

    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(DEEP);getWindow().setNavigationBarColor(Color.WHITE);if(Build.VERSION.SDK_INT>=21)getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);createChannel();if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.POST_NOTIFICATIONS},5);show("Today");}
    void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("routine","Routine reminders",NotificationManager.IMPORTANCE_HIGH);c.setDescription("Daily routine alerts");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
    void gap(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    String day(){return new SimpleDateFormat("yyyyMMdd",Locale.getDefault()).format(new Date());}
    boolean done(int i){return getPreferences(0).getBoolean("done_"+day()+"_"+i,false);}
    String[] names(){return getPreferences(0).getString("names",String.join("|",defaultNames)).split("\\|",-1);}
    String[] times(){return getPreferences(0).getString("times",String.join("|",defaultTimes)).split("\\|",-1);}
    void show(String tab){current=tab;root=col();root.setBackgroundColor(BG);pad(root,20,16,20,8);setContentView(root);ScrollView sc=new ScrollView(this);content=col();pad(content,0,0,0,16);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(tab.equals("Today"))today();else if(tab.equals("Reminders"))reminders();else if(tab.equals("Exercise"))exercise();else videos();navigation();}
    void header(String eyebrow,String title,String sub){TextView e=txt(eyebrow.toUpperCase(Locale.ROOT),11,GREEN,true);e.setLetterSpacing(.12f);content.addView(e);content.addView(txt(title,27,DEEP,true));content.addView(txt(sub,14,MUTED,false));gap(content,20);}
    void card(LinearLayout child,int bottom){child.setBackground(bg(Color.WHITE,20));if(Build.VERSION.SDK_INT>=21)child.setElevation(dp(2));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(bottom);content.addView(child,p);}
    void today(){String date=new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date());header(date,"A better day starts here","Small steps. A little progress every day.");String[] ns=names(),ts=times();int count=0;for(int i=0;i<ns.length;i++)if(done(i))count++;LinearLayout p=col();pad(p,18,18,18,18);p.setBackground(bg(DEEP,22));p.addView(txt("YOUR DAILY PROGRESS",11,Color.rgb(205,225,211),true));gap(p,5);p.addView(txt(count+" / "+ns.length,30,Color.WHITE,true));p.addView(txt(count==ns.length?"Wonderful! You completed your day.":"Keep going. You're doing well.",13,Color.rgb(220,234,223),false));gap(p,14);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(Math.max(1,ns.length));bar.setProgress(count);bar.setProgressTintList(android.content.res.ColorStateList.valueOf( Color.rgb(166,207,174)));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(73,103,85)));p.addView(bar,new LinearLayout.LayoutParams(-1,dp(7)));card(p,22);
        LinearLayout heading=row();heading.addView(txt("Today's routine",19,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));heading.addView(txt("TAP TO COMPLETE",9,MUTED,true));content.addView(heading);gap(content,10);
        for(int i=0;i<ns.length;i++){final int n=i;LinearLayout item=row();pad(item,14,12,14,12);TextView ico=txt(symbol(ns[i],i),20,GREEN,true);ico.setGravity(Gravity.CENTER);ico.setBackground(bg(MINT,14));item.addView(ico,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout words=col();pad(words,12,0,4,0);words.addView(txt(ns[i],15,TEXT,true));words.addView(txt(ts[i],12,MUTED,false));item.addView(words,new LinearLayout.LayoutParams(0,-2,1));CheckBox cb=new CheckBox(this);cb.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{GREEN,MUTED}));cb.setChecked(done(i));item.addView(cb);cb.setOnCheckedChangeListener((v,c)->{getPreferences(0).edit().putBoolean("done_"+day()+"_"+n,c).apply();show("Today");});item.setOnClickListener(v->{getPreferences(0).edit().putBoolean("done_"+day()+"_"+n,!done(n)).apply();show("Today");});card(item,9);}}
    String symbol(String name,int i){String n=name.toLowerCase(Locale.ROOT);if(n.contains("water"))return "💧";if(n.contains("exercise"))return "🏃";if(n.contains("tablet"))return "✚";if(n.contains("walk"))return "🚶";if(n.contains("sleep"))return "☾";if(n.contains("wake"))return "☀";return "•";}
    void reminders(){header("Make time for what matters","Your reminders","A gentle nudge at the right time.");String[] ns=names(),ts=times();for(int i=0;i<ns.length;i++){final int n=i;LinearLayout item=row();pad(item,14,13,12,13);TextView ico=txt(symbol(ns[i],i),20,GREEN,true);ico.setGravity(Gravity.CENTER);ico.setBackground(bg(MINT,13));item.addView(ico,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout info=col();pad(info,12,0,4,0);info.addView(txt(ns[i],15,TEXT,true));info.addView(txt("Every day  •  "+ts[i],12,MUTED,false));item.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView edit=txt("EDIT",10,GREEN,true);item.addView(edit);edit.setOnClickListener(v->editReminder(n));card(item,10);}TextView add=txt("＋   Add a reminder",15,Color.WHITE,true);add.setGravity(Gravity.CENTER);add.setBackground(bg(GREEN,16));pad(add,12,15,12,15);add.setOnClickListener(v->addReminder());content.addView(add,new LinearLayout.LayoutParams(-1,dp(52)));gap(content,12);content.addView(txt("Reminders are saved on this device. Android battery settings may affect delivery times.",12,MUTED,false));}
    void pick(String old,TimeResult cb){String[] a=old.split(":");new TimePickerDialog(this,(v,h,m)->cb.done(String.format(Locale.getDefault(),"%02d:%02d",h,m)),Integer.parseInt(a[0]),Integer.parseInt(a[1]),true).show();}
    interface TimeResult{void done(String value);}
    void editReminder(int i){String[] ns=names(),ts=times();EditText name=new EditText(this);name.setSingleLine(true);name.setText(ns[i]);final String[] time={ts[i]};LinearLayout box=col();pad(box,20,8,20,0);box.addView(name);TextView choose=txt("Time: "+time[0]+"  ·  Change",14,GREEN,true);pad(choose,0,15,0,10);box.addView(choose);choose.setOnClickListener(v->pick(time[0],x->{time[0]=x;choose.setText("Time: "+x+"  ·  Change");}));new AlertDialog.Builder(this).setTitle("Edit reminder").setView(box).setPositiveButton("Save",(d,w)->{String value=name.getText().toString().trim();if(value.isEmpty())return;ArrayList<String>a=new ArrayList<>(Arrays.asList(names())),b=new ArrayList<>(Arrays.asList(times()));a.set(i,value);b.set(i,time[0]);save(a,b);show("Reminders");}).setNeutralButton("Delete",(d,w)->{ArrayList<String>a=new ArrayList<>(Arrays.asList(names())),b=new ArrayList<>(Arrays.asList(times()));a.remove(i);b.remove(i);save(a,b);show("Reminders");}).setNegativeButton("Cancel",null).show();}
    void addReminder(){EditText name=new EditText(this);name.setSingleLine(true);name.setHint("e.g. Drink water");final String[] time={"07:00"};LinearLayout box=col();pad(box,20,8,20,0);box.addView(name);TextView choose=txt("Time: 07:00  ·  Change",14,GREEN,true);pad(choose,0,15,0,10);box.addView(choose);choose.setOnClickListener(v->pick(time[0],x->{time[0]=x;choose.setText("Time: "+x+"  ·  Change");}));new AlertDialog.Builder(this).setTitle("New reminder").setView(box).setPositiveButton("Add",(d,w)->{String value=name.getText().toString().trim();if(value.isEmpty())return;ArrayList<String>a=new ArrayList<>(Arrays.asList(names())),b=new ArrayList<>(Arrays.asList(times()));a.add(value);b.add(time[0]);save(a,b);show("Reminders");}).setNegativeButton("Cancel",null).show();}
    void save(List<String>a,List<String>b){getPreferences(0).edit().putString("names",String.join("|",a)).putString("times",String.join("|",b)).apply();ReminderScheduler.scheduleAll(this);}
    void exercise(){header("Move gently, feel stronger","Your movement plan","A simple 12-minute routine. Go at your own pace.");LinearLayout intro=col();pad(intro,18,17,18,17);intro.setBackground(bg(DEEP,22));intro.addView(txt("TODAY'S SESSION",11,Color.rgb(205,225,211),true));intro.addView(txt("12 minutes",30,Color.WHITE,true));intro.addView(txt("Take short rests whenever you need.",13,Color.rgb(220,234,223),false));card(intro,20);content.addView(txt("Exercise checklist",19,TEXT,true));gap(content,10);for(int i=0;i<exercises.length;i++){final int n=i;LinearLayout item=row();pad(item,14,12,14,12);TextView num=txt(String.format(Locale.getDefault(),"%02d",i+1),14,GREEN,true);num.setGravity(Gravity.CENTER);num.setBackground(bg(MINT,12));item.addView(num,new LinearLayout.LayoutParams(dp(42),dp(42)));LinearLayout words=col();pad(words,12,0,4,0);words.addView(txt(exercises[i],14,TEXT,true));words.addView(txt(details[i],12,MUTED,false));item.addView(words,new LinearLayout.LayoutParams(0,-2,1));CheckBox cb=new CheckBox(this);cb.setButtonTintList(android.content.res.ColorStateList.valueOf(GREEN));cb.setChecked(getPreferences(0).getBoolean("ex_"+day()+"_"+i,false));item.addView(cb);cb.setOnCheckedChangeListener((v,c)->getPreferences(0).edit().putBoolean("ex_"+day()+"_"+n,c).apply());card(item,9);}gap(content,5);content.addView(txt("Stop if you feel pain, dizziness or unusual discomfort. These are general movement suggestions, not medical treatment.",12,MUTED,false));}
    void videos(){header("Learn at your own pace","Helpful resources","Beginner-friendly guidance for everyday movement.");resource("NHS strength & flexibility","Simple guidance for building strength and flexibility.","https://www.nhs.uk/live-well/exercise/strength-and-flexibility-exercises/");resource("Beginner chair exercises","Find gentle seated movement routines.","https://www.youtube.com/results?search_query=beginner+chair+exercises");resource("Gentle morning stretches","Explore easy stretching ideas for your morning.","https://www.youtube.com/results?search_query=gentle+morning+stretching+beginner");}
    void resource(String title,String desc,String url){LinearLayout item=col();pad(item,17,16,17,16);LinearLayout r=row();r.addView(txt(title,16,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));r.addView(txt("↗",18,GREEN,true));item.addView(r);gap(item,6);item.addView(txt(desc,13,MUTED,false));gap(item,12);item.addView(txt("OPEN RESOURCE  →",10,GREEN,true));item.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"Unable to open link",Toast.LENGTH_SHORT).show();}});card(item,12);}
    void navigation(){LinearLayout nav=row();nav.setBackground(bg(Color.WHITE,20));pad(nav,5,6,5,6);String[] tabs={"Today","Reminders","Exercise","Videos"},icons={"⌂","◷","✳","▷"};for(int i=0;i<tabs.length;i++){final String tab=tabs[i];boolean selected=tab.equals(current);LinearLayout item=col();item.setGravity(Gravity.CENTER);pad(item,2,7,2,7);TextView ic=txt(icons[i],20,selected?GREEN:MUTED,true);ic.setGravity(Gravity.CENTER);item.addView(ic);TextView name=txt(tab,10,selected?GREEN:MUTED,selected);name.setGravity(Gravity.CENTER);item.addView(name);if(selected)item.setBackground(bg(MINT,14));item.setOnClickListener(v->show(tab));nav.addView(item,new LinearLayout.LayoutParams(0,dp(58),1));}root.addView(nav,new LinearLayout.LayoutParams(-1,dp(64)));}
}
